/* audio/effects/distortion.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "../../context.js";

export function install(P) {


  function distortionCurveAt(x, drive) {
    const amount = P.clamp(Number(drive) || 0, 0, 1) * 50;
    if (amount < 0.001) return x;
    return Math.tanh(x * (1 + amount)) / Math.tanh(1 + amount);
  }

  function makeDistortionCurve(drive) {
    const samples = 2048;
    const curve = new Float32Array(samples);
    for (let i = 0; i < samples; i++) {
      curve[i] = P.distortionCurveAt((i * 2) / (samples - 1) - 1, drive);
    }
    return curve;
  }
  Object.assign(P, { distortionCurveAt, makeDistortionCurve });
}
